class Solution:
    def has_cycle(self, n: int, edges: list[list[int]]) -> bool:
        adj = {i: [] for i in range(n)}
        for u, v in edges:
            adj[u].append(v)

        # 0 = unvisited, 1 = visiting (in current path), 2 = visited (completely processed)
        state = [0] * n

        def dfs(node):
            if state[node] == 1:
                return True # Found a back-edge indicating a cycle
            if state[node] == 2:
                return False

            state[node] = 1
            for neighbor in adj[node]:
                if dfs(neighbor):
                    return True
            state[node] = 2
            return False

        for i in range(n):
            if state[i] == 0:
                if dfs(i):
                    return True
        return False

